/* Chinese Econ JMC — placement statistics page. Data comes from data.js (generated by scripts/build.py).
   Every chart title states its finding and is computed from the current selection. */
(function () {
  "use strict";

  const D = window.JMC_DATA;
  const $ = (id) => document.getElementById(id);
  if (!D) { $("lede").textContent = "data.js 未找到，请先运行 python scripts/build.py"; return; }
  $("generated").textContent = D.generated;

  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const pct = (k, n) => (n ? Math.round(100 * k / n) : 0);
  const count = (list, f) => list.filter(f).length;

  // placement categories, in stacking order; colors live in stats.css (.k-<key>)
  const TYPES = [
    { key: "fac", label: "教职", test: (c) => c.placement_type === "Faculty" },
    { key: "ntt", label: "非终身轨教职", test: (c) => c.placement_type === "Non-tenure-track" },
    { key: "pd", label: "博后", test: (c) => c.placement_type === "Postdoc" },
    { key: "ind", label: "业界及其他", test: (c) => c.placement_type === "Industry & Other" },
    { key: "def", label: "延期", test: (c) => c.placement_type === "Deferred" },
    { key: "unk", label: "未知", test: (c) => !c.placement },
  ];
  const isFac = (c) => c.placement_type === "Faculty";
  const isFinal = (c) => ["Faculty", "Non-tenure-track", "Postdoc", "Industry & Other"].includes(c.placement_type);
  const facRate = (list) => { const k = list.filter(isFinal); return { fac: count(k, isFac), n: k.length, p: pct(count(k, isFac), k.length) }; };
  const HOME = ["中国大陆", "港澳"];
  const undergrad = (c) => {
    const e = (c.education || []).find((x) => /学士/.test(x.degree));
    if (!e) return null;
    return e.school.replace(/^（中国）|（中国）$/g, "").replace("对外经贸大学", "对外经济贸易大学").trim();
  };
  // PhD program: the school section, or the PhD school in the bio when the section is not a school
  // (e.g. 2024-2025 "中国经济学年会“学术之星”", which has no Chinese school name)
  const phdSchool = (c) => {
    if (c.school_zh) return c.school_zh;
    const e = (c.education || []).find((x) => /博士/.test(x.degree));
    return e ? e.school : c.school;
  };

  // cycles with at least one placement, newest first
  const placedCycles = D.cycles.filter((cy) => D.candidates.some((c) => c.cycle === cy && c.placement));

  // ------------------------------------------------------------ tooltip ----
  const tip = $("tip");
  document.addEventListener("mouseover", (e) => {
    const t = e.target.closest("[data-tip]");
    if (!t) { tip.hidden = true; return; }
    tip.innerHTML = t.dataset.tip;
    tip.hidden = false;
  });
  document.addEventListener("mousemove", (e) => {
    if (tip.hidden) return;
    const pad = 14, w = tip.offsetWidth, h = tip.offsetHeight;
    let x = e.clientX + pad, y = e.clientY + pad;
    if (x + w > window.innerWidth - 8) x = e.clientX - w - pad;
    if (y + h > window.innerHeight - 8) y = e.clientY - h - pad;
    tip.style.transform = `translate(${x}px, ${y}px)`;
  });
  document.addEventListener("mouseleave", () => { tip.hidden = true; });

  const empty = (msg) => `<p class="empty-note">${msg}</p>`;

  // horizontal bar list; rows = [{label, sub?, v, text, tip, cls?} | {group}]; optional dashed reference line at `ref`
  // horizontal bar list; rows = [{label, sub?, v, text, tip, cls?} | {group}].
  // `axis`: percent scale with gridlines and tick labels; `ref`: dashed reference line (e.g. overall average)
  function barList(rows, { max, ref, refLabel, wide, color = "fac", axis = false } = {}) {
    const m = max || Math.max(...rows.filter((r) => !r.group).map((r) => r.v), 1);
    const ticks = axis ? [0, 25, 50, 75, 100].filter((t) => t <= m) : [];
    const grid = ticks.map((t) => `<i class="g" style="left:${(100 * t / m).toFixed(1)}%"></i>`).join("");
    const refX = ref != null ? (100 * ref / m).toFixed(1) : null;
    const refLine = refX != null ? `<i class="ref" style="left:${refX}%"></i>` : "";
    const head = refX != null
      ? `<div class="b-row b-key"><span></span><span class="b-track"><span class="ref-label" style="left:${refX}%">${refLabel}</span></span><span></span></div>`
      : "";
    const body = rows.map((r) => r.group
      ? `<div class="b-group">${esc(r.group)}</div>`
      : `<div class="b-row ${r.cls || ""}" data-tip="${r.tip}">
          <span class="b-label" title="${esc(r.label)}">${esc(r.label)}${r.sub ? `<em>${esc(r.sub)}</em>` : ""}</span>
          <span class="b-track">${grid}${refLine}<span class="fill k-${color}" style="width:${(100 * r.v / m).toFixed(1)}%"></span></span>
          <span class="b-val">${r.text}</span>
        </div>`).join("");
    const foot = axis
      ? `<div class="b-row b-axis"><span></span><span class="b-track">${ticks.map((t) => `<span class="tick" style="left:${(100 * t / m).toFixed(1)}%">${t}%</span>`).join("")}</span><span></span></div>`
      : "";
    return `<div class="bars ${wide ? "wide" : ""}">${head}${body}${foot}</div>`;
  }

  // ---------------------------------------------------- cycle selection ----
  const SEG = [{ v: "all", label: "全部年度" }, ...D.cycles.map((cy) => ({ v: cy, label: cy }))];
  let sel = "all";
  try { const s = localStorage.getItem("jmc-stats-cycle"); if (SEG.some((o) => o.v === s)) sel = s; } catch (e) { /* storage unavailable */ }
  // "all" = every cycle that already has placement information
  const selected = () => D.candidates.filter((c) => (sel === "all" ? placedCycles.includes(c.cycle) : c.cycle === sel));
  const selLabel = () => (sel === "all" ? placedCycles.slice().reverse().join(" 与 ") : sel);

  $("cycle-seg").addEventListener("click", (e) => {
    const b = e.target.closest("button[data-v]");
    if (!b) return;
    sel = b.dataset.v;
    try { localStorage.setItem("jmc-stats-cycle", sel); } catch (err) { /* ignore */ }
    render();
  });

  // ------------------------------------------------------- hero facts ----
  function renderHero(list) {
    const r = facRate(list);
    if (!r.n) { $("hero").innerHTML = empty(`${esc(selLabel())} 还没有去向信息（仍在求职中）。下面的本科来源与博士项目仍可参考。`); return; }
    const fac = list.filter(isFac);
    const home = count(fac, (c) => HOME.includes(c.placement_region)), us = count(fac, (c) => c.placement_region === "美国");
    const insts = topInsts(fac).slice(0, 3);
    const top3 = insts.reduce((s, [, n]) => s + n, 0);
    $("hero").innerHTML = `
      <div class="fact"><div class="big">${r.p}%</div><div class="what">已有最终去向的人拿到教职</div><div class="how">${r.fac} / ${r.n} 人</div></div>
      <div class="fact"><div class="big">${pct(home, fac.length)}%</div><div class="what">的教职在中国大陆与港澳</div><div class="how">美国 ${pct(us, fac.length)}% · 其他海外 ${pct(fac.length - home - us, fac.length)}%</div></div>
      <div class="fact"><div class="big">${pct(top3, fac.length)}%</div><div class="what">的教职去了${insts.map(([k]) => esc(k)).join("、")}</div><div class="how">${top3} / ${fac.length} 人</div></div>`;
  }

  // ------------------------------------- 1. placement mix by cycle (all) ----
  function renderMix() {
    const rows = placedCycles.map((cy) => {
      const list = D.candidates.filter((c) => c.cycle === cy);
      return { cy, n: list.length, parts: TYPES.map((t) => ({ ...t, k: count(list, t.test) })), r: facRate(list) };
    });
    const [last, prev] = rows;
    $("mix-title").textContent = last
      ? `${last.cy} 已知去向中 ${last.r.p}% 为教职` + (prev ? `，${prev.cy} 为 ${prev.r.p}%` : "")
      : "历年去向构成";
    $("mix").innerHTML = `<div class="legend">${TYPES.map((t) => `<span><i class="sw k-${t.key}"></i>${t.label}</span>`).join("")}</div>` +
      rows.map((r) => `
      <div class="mix-row">
        <div class="mix-label"><b>${r.cy}</b><span>${r.n} 人</span></div>
        <div class="stack">${r.parts.filter((p) => p.k).map((p) => {
          const s = pct(p.k, r.n);
          return `<span class="k-${p.key}" style="flex-grow:${p.k}" data-tip="<b>${r.cy}</b><br>${p.label}：${p.k} 人（${s}%）">${s >= 8 ? `<b>${p.label} ${s}%</b>` : ""}</span>`;
        }).join("")}</div>
      </div>`).join("");
  }

  // ------------------------- 2. faculty regions: dumbbell across cycles ----
  function renderRegions() {
    const cys = placedCycles.slice().reverse(); // oldest -> newest
    const facBy = cys.map((cy) => D.candidates.filter((c) => c.cycle === cy && isFac(c)));
    const regionOf = (c) => c.placement_region || "未归类";
    const share = (i, r) => (facBy[i].length ? count(facBy[i], (c) => regionOf(c) === r) / facBy[i].length : 0);
    const regions = [...new Set(facBy.flat().map(regionOf))];
    if (!regions.length) { $("regions-title").textContent = "教职去向地区"; $("regions").innerHTML = empty("暂无教职数据。"); return; }
    const L = cys.length - 1;
    regions.sort((a, b) => share(L, b) - share(L, a) || share(0, b) - share(0, a));
    const max = Math.min(1, Math.ceil(Math.max(...regions.flatMap((r) => cys.map((_, i) => share(i, r)))) * 10) / 10);
    const x = (v) => (100 * v / max).toFixed(1);
    // title: largest destination, plus the biggest mover if it moved >= 5 points
    const top = regions[0];
    let mover = null;
    if (L > 0) {
      for (const r of regions) {
        const d = share(L, r) - share(L - 1, r);
        if (r !== top && (!mover || Math.abs(d) > Math.abs(mover.d))) mover = { r, d };
      }
    }
    $("regions-title").textContent = `${top}占 ${Math.round(100 * share(L, top))}% 的教职` +
      (mover && Math.abs(mover.d) >= 0.05 ? `；${mover.r}从 ${Math.round(100 * share(L - 1, mover.r))}% ${mover.d > 0 ? "升" : "降"}到 ${Math.round(100 * share(L, mover.r))}%` : "");
    const step = max > 0.5 ? 0.25 : 0.1;
    const ticks = []; for (let t = 0; t <= max + 1e-9; t += step) ticks.push(t);
    const legend = `<div class="legend">${cys.map((cy, i) => `<span><i class="dot ${i === L ? "now" : "then"}"></i>${cy}（${facBy[i].length} 人）</span>`).join("")}</div>`;
    const rows = regions.map((r) => {
      const vals = cys.map((_, i) => share(i, r));
      const lo = Math.min(...vals), hi = Math.max(...vals);
      const tipTxt = `<b>${esc(r)}</b><br>` + cys.map((cy, i) => `${cy}：${count(facBy[i], (c) => regionOf(c) === r)} 人（${Math.round(100 * vals[i])}%）`).join("<br>");
      return `<div class="db-row" data-tip="${tipTxt}">
        <span class="b-label">${esc(r)}</span>
        <span class="db-track">${ticks.map((t) => `<i class="grid" style="left:${x(t)}%"></i>`).join("")}<i class="span" style="left:${x(lo)}%;width:${(x(hi) - x(lo)).toFixed(1)}%"></i>${vals.map((v, i) => `<i class="dot ${i === L ? "now" : "then"}" style="left:${x(v)}%"></i>`).join("")}</span>
        <span class="b-val">${Math.round(100 * vals[L])}%</span>
      </div>`;
    }).join("");
    const axis = `<div class="db-row axis"><span></span><span class="db-track">${ticks.map((t) => `<span class="tick" style="left:${x(t)}%">${Math.round(100 * t)}%</span>`).join("")}</span><span></span></div>`;
    $("regions").innerHTML = legend + rows + axis;
  }

  // ------------------------------------------- 5. top hiring institutions ----
  function topInsts(fac) {
    const m = new Map();
    for (const c of fac) { const k = c.placement_inst || "其他（未归类）"; m.set(k, (m.get(k) || 0) + 1); }
    return [...m].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], "zh"));
  }
  function renderInsts(list) {
    const fac = list.filter(isFac);
    const all = topInsts(fac);
    const top = all.filter(([, n]) => n >= 2).slice(0, 12);
    if (!top.length) { $("insts-title").textContent = "主要教职去向机构"; $("insts").innerHTML = empty("暂无录用 2 人及以上的机构。"); return; }
    const region = (name) => (fac.find((c) => c.placement_inst === name) || {}).placement_region || "";
    const t3 = top.slice(0, 3), t3n = t3.reduce((s, [, n]) => s + n, 0);
    $("insts-title").textContent = `${t3.map(([k]) => k).join("、")} 合计招了 ${pct(t3n, fac.length)}% 的教职`;
    const rest = all.length - top.length, restN = fac.length - top.reduce((s, [, n]) => s + n, 0);
    $("insts").innerHTML = barList(top.map(([k, n]) => ({ label: k, sub: region(k), v: n, text: `${n}`,
      tip: `<b>${esc(k)}</b>（${esc(region(k))}）<br>${n} 人，占教职 ${pct(n, fac.length)}%` })), { wide: true }) +
      (rest ? `<p class="note small">另有 ${rest} 家机构共 ${restN} 人。</p>` : "");
  }

  // ---------------------------------------------------------- SVG helpers ----
  const FIELDS = () => (D.field_categories || []).filter((f) => f !== "Other");
  const fieldsOf = (c) => [...new Set((c.fields || []).filter((f) => f !== "Other"))];
  const textW = (t, size) => [...String(t)].reduce((w, ch) => w + (/[⺀-￿]/.test(ch) ? size : size * 0.56), 0);
  const svg = (w, h, body, cls = "") => `<svg class="chart ${cls}" viewBox="0 0 ${w} ${h}" role="img" preserveAspectRatio="xMidYMid meet">${body}</svg>`;
  const niceMax = (v, step) => Math.max(step, Math.ceil(v / step) * step);

  // ------------------------------- 2. flows: outcome type -> region / sector ----
  function renderSankey(list) {
    const fin = list.filter(isFinal);
    if (!fin.length) { $("sankey-title").textContent = "去向全景"; $("sankey").innerHTML = empty("暂无去向数据。"); return; }
    const LEFT = TYPES.filter((t) => ["fac", "ntt", "pd", "ind"].includes(t.key));
    // academic regions with fewer than 3 people fold into 其他地区 so labels stay legible
    const regionN = new Map();
    for (const c of fin) if (c.placement_type !== "Industry & Other") regionN.set(c.placement_region || "未归类", (regionN.get(c.placement_region || "未归类") || 0) + 1);
    const target = (c) => {
      if (c.placement_type === "Industry & Other") return { group: "ind", name: c.placement_sector || "其他行业" };
      const r = c.placement_region || "未归类";
      return { group: "acad", name: regionN.get(r) < 3 || r === "其他" || r === "未归类" ? "其他地区" : r };
    };
    // flows[leftKey][targetName] = n
    const flows = new Map(), totals = new Map(), groupOf = new Map();
    for (const c of fin) {
      const l = typeKey(c), t = target(c);
      groupOf.set(t.name, t.group);
      const k = `${l}|${t.name}`;
      flows.set(k, (flows.get(k) || 0) + 1);
      totals.set(t.name, (totals.get(t.name) || 0) + 1);
    }
    const rightOrder = (g) => [...totals].filter(([k]) => groupOf.get(k) === g)
      .sort((a, b) => (a[0].startsWith("其他") || a[0] === "未归类") - (b[0].startsWith("其他") || b[0] === "未归类") || b[1] - a[1]).map(([k]) => k);
    const right = [...rightOrder("acad"), ...rightOrder("ind")];
    const left = LEFT.filter((t) => fin.some((c) => typeKey(c) === t.key));
    const W = 1000, H = 440, top = 24, x0 = 170, x1 = 760, nw = 12;
    const gapL = 12, gapR = 5, gapGroup = 22;
    const unit = (H - top - 8 - Math.max(gapL * (left.length - 1), gapR * (right.length - 1) + gapGroup)) / fin.length;
    // node positions
    const L = new Map(); let y = top;
    for (const t of left) { const n = count(fin, (c) => typeKey(c) === t.key); L.set(t.key, { y, h: n * unit, n, label: t.label, off: 0 }); y += n * unit + gapL; }
    const R = new Map(); y = top;
    right.forEach((name, i) => {
      if (i > 0 && groupOf.get(name) !== groupOf.get(right[i - 1])) y += gapGroup - gapR;
      const n = totals.get(name); R.set(name, { y, h: n * unit, n, off: 0 }); y += n * unit + gapR;
    });
    let biggest = null, links = "";
    for (const t of left) for (const name of right) {
      const n = flows.get(`${t.key}|${name}`); if (!n) continue;
      const a = L.get(t.key), b = R.get(name), h = n * unit;
      const sy = a.y + a.off, ty = b.y + b.off; a.off += h; b.off += h;
      const xm = (x0 + nw + x1) / 2;
      const d = `M${x0 + nw},${sy} C${xm},${sy} ${xm},${ty} ${x1},${ty} L${x1},${ty + h} C${xm},${ty + h} ${xm},${sy + h} ${x0 + nw},${sy + h} Z`;
      links += `<path class="sk-link sk-${t.key}" d="${d}" data-tip="<b>${t.label} → ${esc(name)}</b><br>${n} 人（占${t.label} ${pct(n, a.n)}%）"></path>`;
      if (!biggest || n > biggest.n) biggest = { n, from: t.label, to: name };
    }
    const nodesL = left.map((t) => { const a = L.get(t.key); return `<rect class="sk-node sk-${t.key}" x="${x0}" y="${a.y}" width="${nw}" height="${Math.max(a.h, 1)}"></rect>
      <text class="sk-label" x="${x0 - 8}" y="${a.y + a.h / 2 + 4}" text-anchor="end">${t.label}<tspan class="sk-n"> ${a.n}</tspan></text>`; }).join("");
    const nodesR = right.map((name) => { const b = R.get(name); return `<rect class="sk-node sk-right" x="${x1}" y="${b.y}" width="${nw}" height="${Math.max(b.h, 1)}" data-tip="<b>${esc(name)}</b><br>${b.n} 人"></rect>
      <text class="sk-label" x="${x1 + nw + 8}" y="${b.y + b.h / 2 + 4}">${esc(name)}<tspan class="sk-n"> ${b.n}</tspan></text>`; }).join("");
    const firstInd = right.find((n) => groupOf.get(n) === "ind");
    const heads = `<text class="sk-head" x="${x1}" y="${top - 10}">学术岗位所在地区</text>` +
      (firstInd ? `<text class="sk-head" x="${x1}" y="${R.get(firstInd).y - 8}">业界：行业</text>` : "") +
      `<text class="sk-head" x="${x0 + nw}" y="${top - 10}" text-anchor="end">去向类型</text>`;
    const defs = `<defs><pattern id="hatch-ntt" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect class="hatch-bg" width="6" height="6"></rect><rect class="hatch-fg" width="2" height="6"></rect></pattern></defs>`;
    $("sankey-title").textContent = `最大的一股去向是${biggest.from} → ${biggest.to}（${biggest.n} 人，占全部最终去向 ${pct(biggest.n, fin.length)}%）`;
    $("sankey").innerHTML = `<div class="scroll-x">${svg(W, H, defs + links + nodesL + nodesR + heads, "sankey")}</div>`;
  }
  const typeKey = (c) => (TYPES.find((t) => t.test(c)) || {}).key;

  // ------------------------- 5. funnel plot: faculty rate vs. sample size ----
  function renderFunnel(list) {
    const all = facRate(list);
    const pts = FIELDS().map((f) => ({ f, ...facRate(list.filter((c) => fieldsOf(c).includes(f))) })).filter((r) => r.n >= 5);
    if (!pts.length || !all.n) { $("funnel-title").textContent = "各研究领域的教职率"; $("funnel").innerHTML = empty("样本不足。"); return; }
    const p0 = all.fac / all.n, Z = 1.96;
    const se = (n) => Math.sqrt(p0 * (1 - p0) / n);
    for (const r of pts) { r.rate = r.fac / r.n; r.hi = r.rate > p0 + Z * se(r.n); r.lo = r.rate < p0 - Z * se(r.n); }
    const W = 1000, H = 420, ml = 76, mr = 24, mt = 14, mb = 40;
    const xMax = niceMax(Math.max(...pts.map((r) => r.n)) * 1.05, 10);
    const X = (n) => ml + (W - ml - mr) * n / xMax, Y = (p) => mt + (H - mt - mb) * (1 - p);
    // 95% band, drawn from n = 3 to xMax
    const nMin = Math.min(...pts.map((r) => r.n));
    const ns = []; for (let n = nMin; n <= xMax; n += 0.5) ns.push(n);
    const up = ns.map((n) => `${X(n).toFixed(1)},${Y(Math.min(1, p0 + Z * se(n))).toFixed(1)}`);
    const dn = ns.slice().reverse().map((n) => `${X(n).toFixed(1)},${Y(Math.max(0, p0 - Z * se(n))).toFixed(1)}`);
    const band = `<polygon class="fn-band" points="${up.join(" ")} ${dn.join(" ")}"></polygon>` +
      `<polyline class="fn-edge" points="${up.join(" ")}"></polyline><polyline class="fn-edge" points="${dn.slice().reverse().join(" ")}"></polyline>`;
    const yt = [0, 0.25, 0.5, 0.75, 1].map((v) => `<line class="gl" x1="${ml}" x2="${W - mr}" y1="${Y(v)}" y2="${Y(v)}"></line><text class="ax" x="${ml - 8}" y="${Y(v) + 4}" text-anchor="end">${v * 100}%</text>`).join("");
    const xs = []; for (let n = 0; n <= xMax; n += xMax > 60 ? 20 : 10) xs.push(n);
    const xt = xs.map((n) => `<text class="ax" x="${X(n)}" y="${H - mb + 18}" text-anchor="middle">${n}</text>`).join("") +
      `<text class="ax ax-title" x="${(ml + W - mr) / 2}" y="${H - 4}" text-anchor="middle">已有最终去向的人数</text>` +
      `<text class="ax ax-title" transform="translate(18 ${(mt + H - mb) / 2}) rotate(-90)" text-anchor="middle">教职率（终身轨教职 / 已有最终去向）</text>`;
    const mean = `<line class="fn-mean" x1="${ml}" x2="${W - mr}" y1="${Y(p0)}" y2="${Y(p0)}"></line><text class="fn-mean-l" x="${W - mr}" y="${Y(p0) - 6}" text-anchor="end">全体 ${all.p}%</text>`;
    // labels: try right / left / above / below, avoid overlaps
    const boxes = pts.map((r) => ({ x: X(r.n) - 6, y: Y(r.rate) - 6, w: 12, h: 12 }));
    const hit = (b) => boxes.some((o) => b.x < o.x + o.w && o.x < b.x + b.w && b.y < o.y + o.h && o.y < b.y + b.h);
    const labels = pts.slice().sort((a, b) => b.n - a.n).map((r) => {
      const px = X(r.n), py = Y(r.rate), w = textW(r.f, 12.5) + 6, h = 16;
      const tries = [[px + 9, py - 7, "start"], [px - 9 - w, py - 7, "end"], [px - w / 2, py - 22, "middle"], [px - w / 2, py + 8, "middle"],
        [px + 9, py - 20, "start"], [px + 9, py + 6, "start"], [px - 9 - w, py - 20, "end"], [px - 9 - w, py + 6, "end"]];
      let pick = tries[0];
      for (const t of tries) { const b = { x: t[0], y: t[1], w, h }; if (!hit(b) && b.x > ml && b.x + w < W - mr) { pick = t; break; } }
      boxes.push({ x: pick[0], y: pick[1], w, h });
      const tx = pick[2] === "start" ? pick[0] : pick[2] === "end" ? pick[0] + w : pick[0] + w / 2;
      return `<text class="fn-label ${r.hi || r.lo ? "sig" : ""}" x="${tx.toFixed(1)}" y="${(pick[1] + 11).toFixed(1)}" text-anchor="${pick[2]}">${esc(r.f)}</text>`;
    }).join("");
    const dots = pts.map((r) => `<circle class="fn-pt ${r.hi || r.lo ? "sig" : ""}" cx="${X(r.n)}" cy="${Y(r.rate)}" r="5.5"
      data-tip="<b>${esc(r.f)}</b><br>教职 ${r.fac} / ${r.n} 人（${r.p}%）<br>${r.hi ? "显著高于全体平均" : r.lo ? "显著低于全体平均" : "在随机波动范围内"}"></circle>`).join("");
    const hi = pts.filter((r) => r.hi).map((r) => r.f), lo = pts.filter((r) => r.lo).map((r) => r.f);
    $("funnel-title").textContent = hi.length || lo.length
      ? [hi.length ? `${hi.join("、")} 教职率显著高于平均` : "", lo.length ? `${lo.join("、")} 显著低于平均` : ""].filter(Boolean).join("；")
      : `各领域教职率都在随机波动范围内（全体 ${all.p}%）`;
    $("funnel").innerHTML = `<div class="legend"><span><i class="dot fn-key sig"></i>显著偏离平均（5% 水平）</span><span><i class="dot fn-key"></i>在波动范围内</span><span><i class="sw fn-key-band"></i>95% 波动范围</span></div>` +
      `<div class="scroll-x">${svg(W, H, yt + band + mean + xt + dots + labels, "funnel")}</div>`;
  }

  // ------------------------------- 6. field co-occurrence matrix ----
  const SHORT = { "Macro": "Macro", "Labor": "Labor", "Finance": "Finance", "Development": "Dev", "Trade": "Trade", "Urban": "Urban",
    "IO": "IO", "Public": "Public", "Econometrics": "Metrics", "Theory": "Theory", "Behavioral & Experimental": "Behav",
    "Political Economy": "PolEcon", "Environment & Energy": "Env", "Health": "Health", "Education": "Educ",
    "Economic History": "History", "Business": "Business" };
  function renderCooc(list) {
    const tot = new Map(); for (const c of list) for (const f of fieldsOf(c)) tot.set(f, (tot.get(f) || 0) + 1);
    const fs = FIELDS().filter((f) => (tot.get(f) || 0) >= 3).sort((a, b) => tot.get(b) - tot.get(a));
    if (fs.length < 2) { $("cooc-title").textContent = "研究领域的组合"; $("cooc").innerHTML = empty("样本不足。"); return; }
    const pair = (a, b) => list.filter((c) => { const x = fieldsOf(c); return x.includes(a) && x.includes(b); });
    const M = fs.map((a, i) => fs.map((b, j) => (j < i ? pair(a, b) : null)));
    const max = Math.max(1, ...M.flat().filter(Boolean).map((g) => g.length));
    let best = null;
    fs.forEach((a, i) => fs.forEach((b, j) => { const g = M[i][j]; if (g && (!best || g.length > best.n)) best = { a, b, n: g.length }; }));
    $("cooc-title").textContent = `最常同时出现的是 ${best.a} + ${best.b}（${best.n} 人）`;
    const head = `<tr><th></th>${fs.map((f) => `<th class="ch" title="${esc(f)}"><span>${esc(SHORT[f] || f)}</span></th>`).join("")}</tr>`;
    const body = fs.map((a, i) => `<tr><th class="rh" title="${esc(a)}">${esc(a)}</th>${fs.map((b, j) => {
      if (j === i) return `<td class="diag" data-tip="<b>${esc(a)}</b><br>共 ${tot.get(a)} 人列出该领域">${tot.get(a)}</td>`;
      if (j > i) return `<td class="void"></td>`;
      const g = M[i][j], n = g.length;
      if (!n) return `<td class="z"></td>`;
      const r = facRate(g), a2 = n / max;
      return `<td class="cell ${a2 > 0.55 ? "hot" : ""}" style="--a:${Math.round(18 + 82 * a2)}%"
        data-tip="<b>${esc(a)} + ${esc(b)}</b><br>${n} 人同时列出${r.n ? `<br>已有最终去向 ${r.n} 人，教职 ${r.fac} 人（${r.p}%）` : ""}">${n}</td>`;
    }).join("")}</tr>`).join("");
    $("cooc").innerHTML = `<div class="scroll-x"><table class="cooc">${head}${body}</table></div>`;
  }

  // --------------------- 7. slope chart: field shares across all cycles ----
  function renderSlope() {
    const cys = D.cycles.slice().reverse(); // oldest -> newest
    const base = cys.map((cy) => D.candidates.filter((c) => c.cycle === cy && fieldsOf(c).length));
    if (cys.length < 2) { $("slope-title").textContent = "研究领域构成的变化"; $("slope").innerHTML = empty("至少需要两个年度。"); return; }
    const share = (i, f) => (base[i].length ? count(base[i], (c) => fieldsOf(c).includes(f)) / base[i].length : 0);
    const fs = FIELDS().filter((f) => cys.some((_, i) => share(i, f) > 0));
    const L = cys.length - 1;
    const delta = (f) => share(L, f) - share(0, f);
    const ups = fs.filter((f) => delta(f) >= 0.03).sort((a, b) => delta(b) - delta(a)).slice(0, 3);
    const downs = fs.filter((f) => delta(f) <= -0.03).sort((a, b) => delta(a) - delta(b)).slice(0, 3);
    const W = 1000, H = 400, ml = 84, mr = 230, mt = 16, mb = 46;
    const yMax = niceMax(Math.max(...fs.flatMap((f) => cys.map((_, i) => share(i, f)))) * 100, 5) / 100;
    const X = (i) => ml + (W - ml - mr) * i / L, Y = (v) => mt + (H - mt - mb) * (1 - v / yMax);
    const yt = []; for (let v = 0; v <= yMax + 1e-9; v += yMax > 0.3 ? 0.1 : 0.05) yt.push(v);
    const grid = yt.map((v) => `<line class="gl" x1="${ml}" x2="${X(L)}" y1="${Y(v)}" y2="${Y(v)}"></line><text class="ax" x="${ml - 10}" y="${Y(v) + 4}" text-anchor="end">${Math.round(v * 100)}%</text>`).join("") +
      cys.map((cy, i) => `<line class="gl vl" x1="${X(i)}" x2="${X(i)}" y1="${mt}" y2="${H - mb}"></line>
        <text class="ax ax-cy" x="${X(i)}" y="${H - mb + 18}" text-anchor="middle">${cy}</text>
        <text class="ax" x="${X(i)}" y="${H - mb + 33}" text-anchor="middle">n=${base[i].length}${i === L && !placedCycles.includes(cy) ? "（名单未完）" : ""}</text>`).join("") +
      `<text class="ax ax-title" transform="translate(18 ${(mt + H - mb) / 2}) rotate(-90)" text-anchor="middle">列出该领域的候选人占比</text>`;
    const cls = (f) => (ups.includes(f) ? "up" : downs.includes(f) ? "down" : "");
    const tipOf = (f) => `<b>${esc(f)}</b><br>` + cys.map((cy, i) => `${cy}：${Math.round(100 * share(i, f))}%`).join("<br>");
    const ordered = fs.slice().sort((a, b) => (cls(a) ? 1 : 0) - (cls(b) ? 1 : 0)); // highlighted lines on top
    const lines = ordered.map((f) => {
      const pts = cys.map((_, i) => `${X(i).toFixed(1)},${Y(share(i, f)).toFixed(1)}`).join(" ");
      return `<g class="sl ${cls(f)}" data-tip="${tipOf(f)}"><polyline class="hit" points="${pts}"></polyline><polyline class="ln" points="${pts}"></polyline>
        ${cys.map((_, i) => `<circle cx="${X(i)}" cy="${Y(share(i, f))}" r="${cls(f) ? 3.5 : 2.5}"></circle>`).join("")}</g>`;
    }).join("");
    // right-hand labels for highlighted fields, spread to avoid overlap
    const lab = [...ups, ...downs].map((f) => ({ f, y: Y(share(L, f)) })).sort((a, b) => a.y - b.y);
    for (let k = 1; k < lab.length; k++) if (lab[k].y - lab[k - 1].y < 15) lab[k].y = lab[k - 1].y + 15;
    const labels = lab.map(({ f, y }) => `<text class="sl-label ${cls(f)}" x="${X(L) + 12}" y="${y + 4}">${esc(f)} ${Math.round(100 * share(0, f))}% → ${Math.round(100 * share(L, f))}%</text>`).join("");
    const r = ups[0], d = downs[0];
    $("slope-title").textContent = [r ? `${r} 占比从 ${Math.round(100 * share(0, r))}% 升至 ${Math.round(100 * share(L, r))}%` : "",
      d ? `${d} 从 ${Math.round(100 * share(0, d))}% 降至 ${Math.round(100 * share(L, d))}%` : ""].filter(Boolean).join("，") || "研究领域构成的变化";
    $("slope").innerHTML = `<div class="legend"><span><i class="sw sl-key up"></i>上升最多</span><span><i class="sw sl-key down"></i>下降最多</span><span><i class="sw sl-key"></i>其他领域</span></div>` +
      `<div class="scroll-x">${svg(W, H, grid + lines + labels, "slope")}</div>`;
  }

  // ------------------------- 6. fields of North American faculty placements ----
  const NA = ["美国", "加拿大"];
  function renderNA(list) {
    const na = list.filter((c) => isFac(c) && NA.includes(c.placement_region));
    if (!na.length) { $("na-title").textContent = "北美教职的研究领域"; $("na").innerHTML = empty("暂无北美教职。"); return; }
    const order = D.field_categories || [];
    const single = new Map(), pair = new Map();
    for (const c of na) {
      const fs = [...new Set((c.fields || []).filter((f) => f !== "Other"))].sort((a, b) => order.indexOf(a) - order.indexOf(b));
      for (const f of fs) single.set(f, (single.get(f) || 0) + 1);
      for (let i = 0; i < fs.length; i++) for (let j = i + 1; j < fs.length; j++) {
        const k = `${fs[i]} + ${fs[j]}`;
        pair.set(k, (pair.get(k) || 0) + 1);
      }
    }
    const sorted = (m) => [...m].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    const s1 = sorted(single), s2 = sorted(pair), p2 = s2.filter(([, n]) => n >= 2);
    const N = na.length;
    const rows = (arr) => arr.map(([k, n]) => ({ label: k, v: n, text: `${n}<em>${pct(n, N)}%</em>`,
      tip: `<b>${esc(k)}</b><br>${n} / ${N} 位北美教职获得者（${pct(n, N)}%）` }));
    const top = s1.filter(([, n]) => n === s1[0][1]).map(([k]) => k);
    $("na-title").textContent = `${N} 个北美教职中，最常见的领域是 ${top.join("、")}（${s1[0][1]} 人）`;
    const max = s1[0][1];
    $("na").innerHTML = `
      <div class="sub-col"><h3>单个领域</h3>${barList(rows(s1), { max, wide: true })}</div>
      <div class="sub-col"><h3>两个领域的组合</h3>${p2.length ? barList(rows(p2), { max, wide: true }) : empty("各组合均只有 1 人。")}
        ${p2.length && s2.length > p2.length ? `<p class="note small">另有 ${s2.length - p2.length} 个组合各 1 人。</p>` : ""}</div>`;
  }

  // ------------------------------------- 7. industry: sectors and employers ----
  const SECTOR_OTHER = "其他";
  function renderIndustry(list) {
    const ind = list.filter((c) => c.placement_type === "Industry & Other");
    if (!ind.length) { $("ind-title").textContent = "业界去向"; $("ind").innerHTML = empty("暂无业界去向数据。"); return; }
    const tally = (key) => {
      const m = new Map();
      for (const c of ind) { const k = key(c); if (k) m.set(k, (m.get(k) || 0) + 1); }
      return [...m].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], "zh"));
    };
    const sectors = tally((c) => c.placement_sector || SECTOR_OTHER);
    sectors.sort((a, b) => (a[0] === SECTOR_OTHER) - (b[0] === SECTOR_OTHER) || b[1] - a[1]); // 其他 last
    const sectorOf = new Map(ind.map((c) => [c.placement_employer, c.placement_sector]));
    const employers = tally((c) => c.placement_employer).filter(([k, n]) => n >= 2 && !k.startsWith("其他"));
    const [top] = sectors;
    $("ind-title").textContent = `业界去向中 ${pct(top[1], ind.length)}% 是${top[0]}`;
    const sectorRows = sectors.map(([k, n]) => ({ label: k, v: n, text: `${pct(n, ind.length)}%<em>${n} 人</em>`,
      tip: `<b>${esc(k)}</b><br>${n} / ${ind.length} 人（${pct(n, ind.length)}%）` }));
    const empRows = employers.slice(0, 10).map(([k, n]) => ({ label: k, sub: sectorOf.get(k) || "", v: n, text: `${n}`,
      tip: `<b>${esc(k)}</b>（${esc(sectorOf.get(k) || "")}）<br>${n} 人，占业界去向 ${pct(n, ind.length)}%` }));
    $("ind").innerHTML = `
      <div class="sub-col"><h3>按类别</h3>${barList(sectorRows, { color: "ind" })}</div>
      <div class="sub-col"><h3>主要雇主（2 人及以上）</h3>${empRows.length ? barList(empRows, { color: "ind", wide: true }) : empty("暂无。")}</div>`;
  }

  // --------------------------------------- 7 & 8. undergrad / PhD origin ----
  function originChart(list, keyFn, titleId, boxId, titleFn) {
    const m = new Map();
    for (const c of list) { const k = keyFn(c); if (k) m.set(k, (m.get(k) || 0) + 1); }
    const top = [...m].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], "zh")).slice(0, 12);
    const known = [...m.values()].reduce((s, n) => s + n, 0);
    if (!top.length) { $(titleId).textContent = titleFn(null); $(boxId).innerHTML = empty("暂无数据。"); return; }
    $(titleId).textContent = titleFn(top, known);
    $(boxId).innerHTML = barList(top.map(([k, n]) => ({ label: k, v: n, text: `${n}`, tip: `<b>${esc(k)}</b><br>${n} 人，占 ${pct(n, known)}%` })), { wide: true, color: "neu" });
  }

  function render() {
    $("cycle-seg").innerHTML = SEG.map((o) =>
      `<button type="button" role="tab" aria-selected="${o.v === sel}" data-v="${o.v}" class="${o.v === sel ? "active" : ""}">${o.label}</button>`).join("");
    const list = selected();
    $("lede").innerHTML = `<b>${esc(selLabel())}</b> · ${list.length} 位候选人`;
    renderHero(list);
    renderSankey(list);
    renderInsts(list);
    renderFunnel(list);
    renderCooc(list);
    renderNA(list);
    renderIndustry(list);
    originChart(list, undergrad, "ug-title", "ug", (top, n) => top
      ? `本科最多来自${top.slice(0, 3).map(([k]) => k).join("、")}（合计 ${pct(top.slice(0, 3).reduce((s, [, k]) => s + k, 0), n)}%）`
      : "本科来源");
    originChart(list, phdSchool, "phd-title", "phd", (top) => top
      ? `${top.slice(0, 3).map(([k]) => k).join("、")} 的中国候选人最多`
      : "博士项目");
  }

  renderMix();
  renderRegions();
  renderSlope();
  render();
})();
